import React from "react";
import {
  AbsoluteFill,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
} from "remotion";
import { springIn, staggeredSpring } from "remotion/motion";
import { BRAND, BRAND_FONT_FACE_CSS } from "remotion/theme";

// =============================================================================
// HeroLaunch — polished launch teaser, overlaid on footage. 4K @ 25fps, 514f.
// Beats follow the client's exact 25fps timecodes; action ends at 389, then a
// ~5s tail holds the final frame for editing room. Transparent root; opaque panels.
// No idle drift — energy comes from snappy springs + a slow connective zoom.
// =============================================================================

export const fps = 25;
export const durationInFrames = 514;
const ACTION_END = 389;

const C = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  cardHi: "#242628",
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  teal: "#7EE0C4",
  red: "#E5484D",
  saas: "#5B6CFF",
};

const MONO = "ui-monospace, 'SF Mono', Menlo, Monaco, Consolas, monospace";
const SANS = BRAND.fonts.primary;
const DISPLAY = BRAND.fonts.marketing;

const CODE_LINES = [
  "async function run(task: string) {",
  "  const plan = await agent.plan(task);",
  "  const code = await agent.write(plan);",
  "  return code;",
  "}",
];
const API_LINE = "const data = await fetch(apiUrl);";
const PROMPT_TEXT = "get me the latest pricing data on this";
const AGENT_REPLY = "I'm sorry, I can't do that.";
const CARD = { number: "4242  4242  4242  4242", name: "NOT A REAL CARD", expiry: "00 / 00", kind: "DEBIT" };

const SHADOW_SOFT = "0 30px 80px rgba(0,0,0,0.35)";
const SHADOW_LIFT = "0 44px 110px rgba(0,0,0,0.42)";

const FONT_CSS =
  BRAND_FONT_FACE_CSS +
  `
@font-face {
  font-family: 'Inter';
  src: url('/assets/fonts/Inter_24pt-SemiBold.ttf') format('truetype');
  font-weight: 600; font-style: normal; font-display: block;
}
`;

const ramp = (frame, stops, values) =>
  interpolate(frame, stops, values, { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
const clamp01 = (v) => Math.max(0, Math.min(1, v));
const lerpColor = (t, a, b) => (t < 0.5 ? a : b);

const KEYWORDS = new Set([
  "import", "from", "const", "let", "var", "await", "async", "function",
  "return", "if", "else", "for", "while", "true", "false", "null", "undefined",
  "new", "class", "extends", "this", "of", "in",
]);

function renderCodeLine(line) {
  const parts = [];
  let i = 0;
  while (i < line.length) {
    const ch = line[i];
    if (ch === " " || ch === "\t") {
      let j = i;
      while (j < line.length && (line[j] === " " || line[j] === "\t")) j++;
      parts.push({ text: line.slice(i, j), color: C.text });
      i = j; continue;
    }
    if (ch === '"' || ch === "'" || ch === "`") {
      const quote = ch;
      let j = i + 1;
      while (j < line.length && line[j] !== quote) { if (line[j] === "\\" && j + 1 < line.length) j += 2; else j++; }
      j = Math.min(j + 1, line.length);
      parts.push({ text: line.slice(i, j), color: C.textMuted });
      i = j; continue;
    }
    if (/[A-Za-z_]/.test(ch)) {
      let j = i;
      while (j < line.length && /[A-Za-z0-9_]/.test(line[j])) j++;
      const word = line.slice(i, j);
      parts.push({ text: word, color: KEYWORDS.has(word) ? C.orange : C.text });
      i = j; continue;
    }
    parts.push({ text: ch, color: C.text });
    i++;
  }
  return parts;
}

// =============================== Mark (X -> check) ===========================
const X_LEN = 70.71;
const CHK_LEN = 70.0;
const Mark = ({ size, xProgress, checkProgress = 0, stroke2Lag = 0, punch = 1 }) => {
  const xVis = clamp01(xProgress);
  const x1 = xVis;
  const x2 = Math.max(0, (xVis - stroke2Lag) / (1 - stroke2Lag || 1));
  const chk = clamp01(checkProgress);
  const strokeW = size * 0.018;
  const xGlow = xVis > 0.02 ? `drop-shadow(0 0 ${size * 0.05}px rgba(229,72,77,0.45))` : "none";
  const chkGlow = chk > 0.02 ? `drop-shadow(0 0 ${size * 0.06}px rgba(126,224,196,0.55))` : "none";
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ overflow: "visible", transform: `scale(${punch})` }}>
      <g style={{ filter: xGlow, opacity: xVis > 0.001 ? 1 : 0 }}>
        <line x1={25} y1={25} x2={75} y2={75} stroke={C.red} strokeWidth={strokeW} strokeLinecap="round" strokeDasharray={X_LEN} strokeDashoffset={interpolate(x1, [0, 1], [X_LEN, 0])} />
        <line x1={75} y1={25} x2={25} y2={75} stroke={C.red} strokeWidth={strokeW} strokeLinecap="round" strokeDasharray={X_LEN} strokeDashoffset={interpolate(x2, [0, 1], [X_LEN, 0])} />
      </g>
      <polyline points="24,52 44,70 76,30" fill="none" stroke={C.teal} strokeWidth={strokeW} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={CHK_LEN} strokeDashoffset={interpolate(chk, [0, 1], [CHK_LEN, 0])} style={{ filter: chkGlow, opacity: chk > 0.001 ? 1 : 0 }} />
    </svg>
  );
};

const Centered = ({ children }) => (
  <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", pointerEvents: "none" }}>{children}</div>
);

const PauseBars = ({ p, h }) => {
  const w = h * 0.3;
  const bar = (delay) => ({
    width: w,
    height: h * interpolate(Math.max(0, p - delay), [0, 0.5], [0.5, 1], { extrapolateRight: "clamp" }),
    borderRadius: w * 0.4, background: C.teal,
    opacity: interpolate(Math.max(0, p - delay), [0, 0.3], [0, 1], { extrapolateRight: "clamp" }),
  });
  return (<div style={{ display: "flex", gap: w * 0.6, alignItems: "center" }}><div style={bar(0)} /><div style={bar(0.12)} /></div>);
};

// =============================== Beats 1-5: WindowStage ======================
const WindowStage = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const inP = springIn(frame, vfps, 0, "SNAPPY");
  const inScale = interpolate(inP, [0, 1], [0.9, 1]);
  const inBlur = interpolate(inP, [0, 1], [10, 0]);
  const inY = interpolate(inP, [0, 1], [base * 0.05, 0]);

  const termOpacity = ramp(frame, [80, 88], [1, 0]);
  const sizeProg = springIn(frame, vfps, 86, "SNAPPY");
  const chatOpacity = ramp(frame, [98, 110], [0, 1]);
  const morphDip = 1 - 0.04 * ramp(frame, [86, 93, 102], [0, 1, 0]);

  const termW = width * 0.56, termH = height * 0.45;
  const chatW = width * 0.46, chatH = height * 0.3;
  const signW = width * 0.34, signH = height * 0.4; // morph target -> sign-up window
  const chatGeoW = interpolate(sizeProg, [0, 1], [termW, chatW]);
  const chatGeoH = interpolate(sizeProg, [0, 1], [termH, chatH]);

  const morphOut = springIn(frame, vfps, 175, "SNAPPY"); // box reforms into the sign-up footprint
  const exitFade = ramp(frame, [187, 200], [1, 0]);
  const boxW = interpolate(morphOut, [0, 1], [chatGeoW, signW]);
  const boxH = interpolate(morphOut, [0, 1], [chatGeoH, signH]);

  const opacity = inP * exitFade;
  const ty = inY;
  const scale = inScale * morphDip;
  const chatLayerOpacity = chatOpacity * ramp(frame, [175, 183], [1, 0]);

  const codeFont = base * 0.0182;
  const lineH = codeFont * 1.74;
  const caretOn = Math.floor(frame / 12) % 2 === 0;
  const shimmerOpacity = ramp(frame, [6, 16], [0, 1]) * ramp(frame, [30, 38], [1, 0]);
  const planP = springIn(frame, vfps, 23, "ELASTIC"); // "plan mode on" pops in at 0:00:00:23

  const renderLine = (line, idx, baseDelay, flash) => {
    const t = staggeredSpring(frame, vfps, idx, baseDelay, 1.2, "SNAPPY");
    const wipe = interpolate(t, [0, 1], [100, 0]);
    const flashAmt = flash ? ramp(frame, [baseDelay, baseDelay + 5, baseDelay + 18], [0, 1, 0]) : 0;
    return (
      <div key={`${baseDelay}-${idx}`} style={{ display: "flex", gap: codeFont * 1.1, minHeight: lineH, alignItems: "baseline", opacity: t, clipPath: `inset(0 ${wipe}% 0 0)`, transform: `translateY(${interpolate(t, [0, 1], [base * 0.004, 0])}px)` }}>
        <span style={{ color: C.textSubtle, width: codeFont * 1.4, textAlign: "right", flexShrink: 0, opacity: 0.6 }}>{idx + 1}</span>
        <span style={{ whiteSpace: "pre", textShadow: flashAmt > 0.01 ? `0 0 ${base * 0.016 * flashAmt}px rgba(248,102,6,${0.85 * flashAmt})` : "none" }}>
          {renderCodeLine(line).map((part, j) => (<span key={j} style={{ color: part.color }}>{part.text}</span>))}
        </span>
      </div>
    );
  };

  const userIn = springIn(frame, vfps, 100, "SNAPPY");
  const userX = interpolate(userIn, [0, 1], [base * 0.06, 0]);
  const replyP = springIn(frame, vfps, 142, "SNAPPY");
  const replyY = interpolate(replyP, [0, 1], [chatH * 0.95, 0]);
  const replyOpacity = ramp(frame, [142, 150], [0, 1]);
  const textFont = base * 0.0152;

  return (
    <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{
        position: "relative", width: boxW, height: boxH, opacity,
        transform: `translateY(${ty}px) scale(${scale})`,
        filter: inBlur > 0.05 ? `blur(${inBlur}px)` : "none",
        background: C.card, border: `1px solid ${C.border}`, borderRadius: base * 0.018,
        overflow: "hidden", boxShadow: SHADOW_SOFT,
      }}>
        {/* TERMINAL LAYER */}
        <div style={{ position: "absolute", inset: 0, opacity: termOpacity, display: termOpacity < 0.01 ? "none" : "flex", flexDirection: "column", fontFamily: MONO, filter: termOpacity < 0.99 ? `blur(${(1 - termOpacity) * 6}px)` : "none" }}>
          <div style={{ display: "flex", alignItems: "center", gap: base * 0.009, padding: `${base * 0.013}px ${base * 0.02}px`, borderBottom: `1px solid ${C.border}` }}>
            {[0.9, 0.6, 0.35].map((o, i) => (<div key={i} style={{ width: base * 0.0095, height: base * 0.0095, borderRadius: "50%", background: C.orange, opacity: o }} />))}
            <div style={{ marginLeft: base * 0.012, fontSize: base * 0.015, color: C.textMuted }}>agent.ts</div>
          </div>
          <div style={{ position: "relative", flex: 1, padding: `${base * 0.022}px ${base * 0.028}px`, fontSize: codeFont, lineHeight: 1.74, color: C.text }}>
            <div style={{ position: "absolute", top: base * 0.024, left: base * 0.028, right: base * 0.028, opacity: shimmerOpacity }}>
              {[0.7, 0.45, 0.6].map((w, i) => (
                <div key={i} style={{ height: codeFont * 0.85, width: `${w * 100}%`, marginBottom: lineH - codeFont * 0.85, borderRadius: codeFont * 0.4, background: C.border, opacity: 0.5 + 0.4 * (0.5 + 0.5 * Math.sin((frame + i * 7) / 6)) }} />
              ))}
            </div>
            <div>
              {CODE_LINES.map((l, i) => renderLine(l, i, 36, false))}
              <div style={{ minHeight: lineH * 0.5 }} />
              {renderLine(API_LINE, CODE_LINES.length + 1, 58, true)}
            </div>
          </div>
          <div style={{ padding: `${base * 0.006}px ${base * 0.028}px ${base * 0.02}px` }}>
            <div style={{ display: "flex", alignItems: "center", gap: base * 0.01, border: `1px solid ${C.border}`, borderRadius: base * 0.008, padding: `${base * 0.011}px ${base * 0.016}px`, opacity: Math.min(1, inP * 1.2) }}>
              <span style={{ color: C.teal, fontSize: codeFont, opacity: 0.9 }}>&gt;</span>
              <span style={{ width: codeFont * 0.52, height: codeFont * 1.05, background: C.text, opacity: caretOn ? 0.85 : 0, borderRadius: 2 }} />
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: base * 0.009, marginTop: base * 0.011, paddingLeft: base * 0.002 }}>
              <div style={{ display: "flex", alignItems: "center", gap: base * 0.007, padding: `${base * 0.005}px ${base * 0.0095}px`, borderRadius: base * 0.05, background: "rgba(126,224,196,0.12)", boxShadow: `0 0 ${base * 0.014}px rgba(126,224,196,0.42)`, opacity: planP, transform: `scale(${interpolate(planP, [0, 1], [0.7, 1])})`, transformOrigin: "left center" }}>
                <PauseBars p={planP} h={codeFont * 0.92} />
                <span style={{ color: C.teal, fontSize: codeFont * 0.9, fontFamily: MONO }}>plan mode on</span>
              </div>
            </div>
          </div>
        </div>

        {/* CHAT LAYER */}
        <div style={{ position: "absolute", inset: 0, opacity: chatLayerOpacity, display: chatLayerOpacity < 0.01 ? "none" : "block" }}>
          <div style={{ position: "absolute", top: base * 0.03, right: base * 0.026, maxWidth: "72%", opacity: userIn, transform: `translate(${userX}px, ${interpolate(userIn, [0, 1], [base * 0.012, 0])}px)`, background: "#2c2e30", borderRadius: base * 0.014, padding: `${base * 0.016}px ${base * 0.02}px`, fontFamily: SANS, fontSize: textFont, fontWeight: 500, color: C.text, lineHeight: 1.45 }}>
            {PROMPT_TEXT}
          </div>
          <div style={{ position: "absolute", bottom: base * 0.03, left: base * 0.026, maxWidth: "72%", opacity: replyOpacity, transform: `translateY(${replyY}px)`, background: C.cardHi, border: `1px solid ${C.border}`, borderRadius: base * 0.014, padding: `${base * 0.016}px ${base * 0.02}px`, fontFamily: SANS, fontSize: textFont, fontWeight: 500, color: C.textMuted, lineHeight: 1.45 }}>
            {AGENT_REPLY}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// =============================== Beats 6-9: FailureStage =====================
const Field = ({ base, label, focus, masked }) => (
  <div style={{ borderRadius: base * 0.009, border: `1.5px solid ${lerpColor(focus, C.border, C.saas)}`, background: C.cardHi, padding: `${base * 0.013}px ${base * 0.016}px`, boxShadow: focus > 0.05 ? `0 0 ${base * 0.012 * focus}px rgba(91,108,255,${0.5 * focus})` : "none" }}>
    <div style={{ fontFamily: SANS, fontSize: base * 0.0095, color: C.textSubtle, letterSpacing: "0.06em" }}>{label}</div>
    <div style={{ display: "flex", alignItems: "center", height: base * 0.02 }}>
      <div style={{ fontFamily: SANS, fontSize: base * 0.014, color: C.textSubtle, opacity: 0.5 }}>{masked ? "••••••••" : ""}</div>
      <div style={{ width: base * 0.0015, height: base * 0.018, background: C.saas, opacity: focus > 0.3 ? 0.9 : 0, marginLeft: 1 }} />
    </div>
  </div>
);

const FailureStage = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // Local frame (Sequence from=175): 0..338. global = local + 175.
  // sign-up REFORMS in place from the chat-window footprint (no swipe-in)
  const signW = width * 0.34, signH = height * 0.4; // matches WindowStage morph target
  const signupReform = springIn(frame, vfps, 4, "SNAPPY");
  const signupContentIn = ramp(frame, [12, 26], [0, 1]);
  const signupScale = interpolate(signupReform, [0, 1], [0.96, 1]);
  const signupX = springIn(frame, vfps, 28, "SNAPPY");
  const signupRecoil = 1 - 0.02 * ramp(frame, [44, 47, 54], [0, 1, 0]);
  const signupShake = Math.sin((frame - 44) * 1.5) * base * 0.002 * ramp(frame, [44, 45, 52], [0, 1, 0]);
  const signupOut = ramp(frame, [51, 65], [0, 1]); // swipes out left as the card arrives
  const signupTX = -signupOut * width * 0.7;
  const signupOpacity = signupReform * (1 - signupOut);
  const signupPunch = 1 + 0.06 * ramp(frame, [38, 42, 48], [0, 1, 0]);
  const fieldFocus = ramp(frame, [16, 22, 28], [0, 1, 0]);

  const cardIn = springIn(frame, vfps, 51, "SNAPPY");
  const cardTX = interpolate(cardIn, [0, 1], [width * 0.7, 0]);
  const cardRotY = interpolate(cardIn, [0, 1], [18, 0]);
  const sheen = ramp(frame, [74, 86], [-1.3, 1.3]);
  const cardXraw = springIn(frame, vfps, 96, "SNAPPY");
  const cardRecoil = 1 - 0.02 * ramp(frame, [110, 113, 120], [0, 1, 0]);

  const sat = ramp(frame, [116, 130, 164, 181], [1, 0.82, 0.82, 1.06]);
  const bright = ramp(frame, [116, 130, 164, 181], [1, 0.92, 0.92, 1.04]);

  const compress = 1 - 0.012 * ramp(frame, [160, 163, 167], [0, 1, 0]);
  const retract = ramp(frame, [164, 178], [0, 1]);
  const cardX = cardXraw * (1 - retract);
  const check = springIn(frame, vfps, 178, "SNAPPY");
  const lift = springIn(frame, vfps, 188, "SNAPPY");
  const liftY = -base * 0.02 * lift;
  const liftScale = 1 + 0.05 * lift;
  const cardMarkPunch = 1 + 0.06 * ramp(frame, [106, 110, 116], [0, 1, 0]) + 0.09 * ramp(frame, [198, 203, 209], [0, 1, 0]);
  const stripeGlow = ramp(frame, [178, 196], [0, 1]);
  const warmGlow = ramp(frame, [164, 181, 214], [0, 0.5, 0.32]);

  const cardW = width * 0.4;
  const cardH = cardW * 0.62;
  const markSize = base * 0.27;

  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ position: "relative", width: signW, height: signH, transform: `translateX(${signupTX + signupShake}px) scale(${signupScale * signupRecoil})`, opacity: signupOpacity, background: C.card, border: `1px solid ${C.border}`, borderRadius: base * 0.018, overflow: "hidden", boxShadow: SHADOW_SOFT }}>
          <div style={{ position: "absolute", inset: 0, padding: `${base * 0.034}px ${base * 0.032}px`, display: "flex", flexDirection: "column", justifyContent: "space-between", opacity: signupContentIn }}>
            <div>
              <div style={{ fontFamily: DISPLAY, fontWeight: 700, fontSize: base * 0.026, color: C.text }}>Create your account</div>
              <div style={{ fontFamily: SANS, fontSize: base * 0.014, color: C.textSubtle, marginTop: base * 0.008 }}>Start your free trial — no setup required.</div>
            </div>
            <div>
              <Field base={base} label="Email" focus={fieldFocus} />
              <div style={{ height: base * 0.014 }} />
              <Field base={base} label="Password" focus={0} masked />
            </div>
            <div style={{ height: base * 0.05, borderRadius: base * 0.01, background: C.saas, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: SANS, fontWeight: 600, fontSize: base * 0.016, color: "#fff" }}>Sign up</div>
          </div>
          <Centered><Mark size={markSize} xProgress={clamp01(signupX) * (1 - signupOut)} stroke2Lag={0.18} punch={signupPunch} /></Centered>
        </div>
      </AbsoluteFill>

      <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center", perspective: base * 2.2 }}>
        <div style={{ position: "relative", opacity: cardIn, transform: `translateX(${cardTX}px) translateY(${liftY}px) scale(${liftScale * cardRecoil * compress})`, filter: `saturate(${sat}) brightness(${bright})` }}>
          <div style={{ position: "absolute", inset: `-${base * 0.06}px`, borderRadius: base * 0.05, background: `radial-gradient(closest-side, rgba(248,102,6,${0.45 * warmGlow}), rgba(248,102,6,0))`, filter: `blur(${base * 0.02}px)`, opacity: warmGlow > 0.01 ? 1 : 0 }} />
          <div style={{ position: "relative", width: cardW, height: cardH, borderRadius: base * 0.022, overflow: "hidden", transform: `rotateY(${cardRotY}deg)`, background: "linear-gradient(135deg, #2a2c2f 0%, #1b1c1e 60%, #161718 100%)", border: `1px solid ${C.border}`, boxShadow: lift > 0.02 ? SHADOW_LIFT : SHADOW_SOFT, padding: `${base * 0.03}px ${base * 0.034}px`, display: "flex", flexDirection: "column", justifyContent: "space-between" }}>
            <div style={{ position: "absolute", top: 0, left: 0, width: base * 0.012, height: "100%", background: C.orange, opacity: 0.55 + 0.45 * stripeGlow, boxShadow: stripeGlow > 0.02 ? `0 0 ${base * 0.02 * stripeGlow}px rgba(248,102,6,0.7)` : "none" }} />
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div style={{ fontFamily: SANS, fontWeight: 600, fontSize: base * 0.015, color: C.textMuted, letterSpacing: "0.12em" }}>{CARD.kind}</div>
              <div style={{ display: "flex" }}>
                <div style={{ width: base * 0.03, height: base * 0.03, borderRadius: "50%", background: "rgba(248,102,6,0.85)" }} />
                <div style={{ width: base * 0.03, height: base * 0.03, borderRadius: "50%", background: "rgba(255,255,255,0.32)", marginLeft: -base * 0.012 }} />
              </div>
            </div>
            <div style={{ width: base * 0.05, height: base * 0.038, borderRadius: base * 0.006, background: "linear-gradient(135deg,#d9b56a,#a07c33)", marginTop: -base * 0.01 }} />
            <div style={{ fontFamily: "ui-monospace, Menlo, monospace", fontSize: base * 0.026, color: C.text, letterSpacing: "0.06em" }}>{CARD.number}</div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end" }}>
              <div>
                <div style={{ fontFamily: SANS, fontSize: base * 0.0095, color: C.textSubtle, letterSpacing: "0.14em" }}>CARD HOLDER</div>
                <div style={{ fontFamily: SANS, fontWeight: 600, fontSize: base * 0.015, color: C.textMuted, letterSpacing: "0.06em" }}>{CARD.name}</div>
              </div>
              <div>
                <div style={{ fontFamily: SANS, fontSize: base * 0.0095, color: C.textSubtle, letterSpacing: "0.14em" }}>EXPIRES</div>
                <div style={{ fontFamily: SANS, fontWeight: 600, fontSize: base * 0.015, color: C.textMuted }}>{CARD.expiry}</div>
              </div>
            </div>
            <div style={{ position: "absolute", top: 0, bottom: 0, left: 0, width: "55%", transform: `translateX(${sheen * cardW}px) skewX(-18deg)`, background: "linear-gradient(90deg, rgba(255,255,255,0), rgba(255,255,255,0.14), rgba(255,255,255,0))", opacity: sheen > -1.2 && sheen < 1.2 ? 1 : 0 }} />
          </div>
          <Centered><Mark size={markSize} xProgress={cardX} checkProgress={check} stroke2Lag={0.18} punch={cardMarkPunch} /></Centered>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

